<?php

namespace Database\Factories;

trait FakeImageTrait
{
    private $images = [
        '',
        '',
        '',
    ];

    public function getFakeImage($path = ''): string
    {
        $imageIndex = random_int(0, count($this->images) - 1);
        $imageContent = $this->images[$imageIndex];
        $image = base64_decode($imageContent);

        $prefix = $path ? rtrim($path, '/').'/' : '';
        $imageName = $prefix.\Str::random(26).'.jpg';

        \Storage::disk('local')->put($imageName, $image);

        return $imageName;
    }
}
